Photophore::Platform::Wayland::XdgShell::~XdgShell() {
  destroy();
}

auto Photophore::Platform::Wayland::XdgShell::recognizes(const char* interface)
    -> Bool {
  return strcmp(interface, xdg_wm_base_interface.name) == 0;
}

auto Photophore::Platform::Wayland::XdgShell::bind(void* registry, U32 name)
    -> Bool {
  if (wm_base) {
    return True;
  }

  // The owner uses only version one requests even though the shared tables
  // describe the newer protocol. Binding that version keeps the compositor's
  // event contract within the dispatcher behavior implemented here.
  wm_base = static_cast<wl_proxy*>(
      wl_registry_bind(as_registry(registry), name, &xdg_wm_base_interface, 1));
  if (!wm_base) {
    return False;
  }

  static const auto wm_dispatch =
      +[](const void*, void* target, uint32_t opcode, const wl_message*,
          wl_argument* arguments) -> int {
    enum class Event : uint32_t { Ping };
    switch (static_cast<Event>(opcode)) {
    case Event::Ping: {
      void* shell = target;
      U32 serial = arguments[0].u;
      wl_proxy_marshal_flags(
          as_proxy(shell), 3, nullptr, wl_proxy_get_version(as_proxy(shell)), 0,
          serial);
      return 0;
    }
    }
    return -1;
  };
  if (wl_proxy_add_dispatcher(as_proxy(wm_base), wm_dispatch, this, this) !=
      0) {
    wl_proxy_marshal_flags(
        as_proxy(wm_base), 0, nullptr, wl_proxy_get_version(as_proxy(wm_base)),
        WL_MARSHAL_FLAG_DESTROY);
    wm_base = nullptr;
    return False;
  }

  return True;
}

auto Photophore::Platform::Wayland::XdgShell::create_toplevel(
    void* wayland_surface,
    const char* title,
    const char* application_id,
    Events new_events) -> Bool {
  if (!wm_base || surface || toplevel) {
    return False;
  }

  // Each role depends on the proxy created before it. If construction stops,
  // release the partial role chain while leaving Window's wl_surface alive.
  // Callback storage stays borrowed until destroy removes these proxies.
  events = new_events;
  this->wayland_surface = wayland_surface;
  surface = wl_proxy_marshal_flags(
      as_proxy(wm_base), 2, &xdg_surface_interface,
      wl_proxy_get_version(as_proxy(wm_base)), 0, nullptr,
      as_surface(wayland_surface));
  if (!surface) {
    events = {};
    this->wayland_surface = nullptr;
    return False;
  }

  static const auto surface_dispatch =
      +[](const void* context, void* target, uint32_t opcode, const wl_message*,
          wl_argument* arguments) -> int {
    enum class Event : uint32_t { Configure };
    void* data = const_cast<void*>(context);
    switch (static_cast<Event>(opcode)) {
    case Event::Configure: {
      void* surface = target;
      U32 serial = arguments[0].u;
      // Acknowledge before committing state for this configuration. The
      // compositor associates the following commit with this serial.
      wl_proxy_marshal_flags(
          as_proxy(surface), 4, nullptr,
          wl_proxy_get_version(as_proxy(surface)), 0, serial);
      auto* shell = static_cast<Photophore::Platform::Wayland::XdgShell*>(data);
      wl_surface_commit(as_surface(shell->wayland_surface));
      return 0;
    }
    }
    return -1;
  };
  if (wl_proxy_add_dispatcher(
          as_proxy(surface), surface_dispatch, this, this) != 0) {
    wl_proxy_marshal_flags(
        as_proxy(surface), 0, nullptr, wl_proxy_get_version(as_proxy(surface)),
        WL_MARSHAL_FLAG_DESTROY);
    surface = nullptr;
    events = {};
    this->wayland_surface = nullptr;
    return False;
  }

  toplevel = wl_proxy_marshal_flags(
      as_proxy(surface), 1, &xdg_toplevel_interface,
      wl_proxy_get_version(as_proxy(surface)), 0, nullptr);
  if (!toplevel) {
    wl_proxy_marshal_flags(
        as_proxy(surface), 0, nullptr, wl_proxy_get_version(as_proxy(surface)),
        WL_MARSHAL_FLAG_DESTROY);
    surface = nullptr;
    events = {};
    this->wayland_surface = nullptr;
    return False;
  }

  static const auto toplevel_dispatch =
      +[](const void* context, void*, uint32_t opcode, const wl_message*,
          wl_argument* arguments) -> int {
    enum class Event : uint32_t {
      Configure,
      Close,
      ConfigureBounds,
      WmCapabilities
    };
    void* data = const_cast<void*>(context);
    switch (static_cast<Event>(opcode)) {
    case Event::Configure: {
      S32 width = arguments[0].i;
      S32 height = arguments[1].i;
      auto& shell =
          *static_cast<Photophore::Platform::Wayland::XdgShell*>(data);
      if (shell.events.configure) {
        shell.events.configure(shell.events.context, width, height);
      }
      return 0;
    }
    case Event::Close: {
      auto& shell =
          *static_cast<Photophore::Platform::Wayland::XdgShell*>(data);
      if (shell.events.close) {
        shell.events.close(shell.events.context);
      }
      return 0;
    }
    case Event::ConfigureBounds:
    case Event::WmCapabilities:
      return 0;
    }
    return -1;
  };
  if (wl_proxy_add_dispatcher(
          as_proxy(toplevel), toplevel_dispatch, this, this) != 0) {
    wl_proxy_marshal_flags(
        as_proxy(toplevel), 0, nullptr,
        wl_proxy_get_version(as_proxy(toplevel)), WL_MARSHAL_FLAG_DESTROY);
    toplevel = nullptr;
    wl_proxy_marshal_flags(
        as_proxy(surface), 0, nullptr, wl_proxy_get_version(as_proxy(surface)),
        WL_MARSHAL_FLAG_DESTROY);
    surface = nullptr;
    events = {};
    this->wayland_surface = nullptr;
    return False;
  }

  wl_proxy_marshal_flags(
      as_proxy(toplevel), 2, nullptr, wl_proxy_get_version(as_proxy(toplevel)),
      0, title);
  wl_proxy_marshal_flags(
      as_proxy(toplevel), 3, nullptr, wl_proxy_get_version(as_proxy(toplevel)),
      0, application_id);
  return True;
}

auto Photophore::Platform::Wayland::XdgShell::destroy() -> void {
  if (toplevel) {
    wl_proxy_marshal_flags(
        as_proxy(toplevel), 0, nullptr,
        wl_proxy_get_version(as_proxy(toplevel)), WL_MARSHAL_FLAG_DESTROY);
    toplevel = nullptr;
  }

  if (surface) {
    wl_proxy_marshal_flags(
        as_proxy(surface), 0, nullptr, wl_proxy_get_version(as_proxy(surface)),
        WL_MARSHAL_FLAG_DESTROY);
    surface = nullptr;
  }

  if (wm_base) {
    wl_proxy_marshal_flags(
        as_proxy(wm_base), 0, nullptr, wl_proxy_get_version(as_proxy(wm_base)),
        WL_MARSHAL_FLAG_DESTROY);
    wm_base = nullptr;
  }

  events = {};
  wayland_surface = nullptr;
}

